  "prediction_basis_card_ids": [
    "C01","C02","C05","C06","C07","C08","C11","C13","C14",
    "C33","C35","C40","C43","C45","C52"
  ],
  "claims": [
    {
      "claim": "L1 gold-context records in fasted/non-cirrhotic oral settings report absolute F values well above 20% (melperone 54–67%, vernakalant 58–71%, suvorexant 82%, propylthiouracil 77%, BI 425809 71.6%, levofloxacin ~100%); propylthiouracil is a thiourea-containing reference and pentazocine is an N-prenyl amine reference (F ~0.68–0.70 in cirrhosis).",
      "card_ids": ["C01","C02","C03","C05","C06","C07","C08","C09","C11","C13","C14"]
    },
    {
      "claim": "L4/L5 records show high intestinal absorption/permeability and minimal or no efflux for lipophilic, chloro-substituted, basic/heteroaromatic reference molecules, supporting the absorption component of F.",
      "card_ids": ["C33","C35","C40","C43","C45","C52"]
    },
    {
      "claim": "L6 hepatic-clearance records are mixed: high CLint values for pyrazole-benzamide and sulfonyl-guanidine triazole reference molecules (C57,C58,C59,C65,C67) are structurally distinct from the query, while prenylated flavonoids (C60,C66) and chloro-tricyclic analogs (C62,C64,C68) show low-to-moderate clearance; no query-specific hepatic clearance measurement is available.",
      "card_ids": ["C57","C58","C59","C60","C61","C62","C63","C64","C65","C66","C67","C68"]
    },
    {
      "claim": "No affirmative threshold-relevant evidence supports F<20%; high CLint alone is not a direct oral-bioavailability result and can be compatible with F>=20%.",
      "card_ids": ["C57","C58","C59","C65","C67"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C57","C58","C59","C60","C61","C62","C63","C64","C65","C66","C67","C68"]
    }
  ],
  "evidence_gaps": [
    "No direct query-specific absolute oral bioavailability or matched oral-versus-IV exposure measurement is available.",
    "No query-specific hepatic clearance or metabolic-stability measurement; L6 records are for reference molecules with structural differences.",
    "No query-specific aqueous solubility/dissolution data; high logP/logD and BCS II-like references indicate a possible solubility limitation.",
    "Pentazocine L1 records are in cirrhotic patients, limiting direct transfer to an unspecified/healthy condition.",
    "L3 Cmax records do not quantify systemic F."
  ],
  "decision_summary": "Predicted high (F >= 20%) with moderate confidence. L1 gold-context records uniformly report F >20%, including thiourea and N-prenyl amine references; L4/L5 support high absorption and minimal efflux. L6 hepatic-clearance evidence is mixed and not query-specific: high CLint records are structurally distinct, while prenylated and chloro-tricyclic analogs show low-to-moderate clearance. No affirmative low-F evidence is present, so the high prediction is retained."
}

